ALTER TABLE minicore.currencies ADD COLUMN decimal_places SMALLINT;

UPDATE minicore.currencies SET decimal_places = 2 WHERE currency_code = 'USD';
UPDATE minicore.currencies SET decimal_places = 2 WHERE currency_code = 'BRL';
UPDATE minicore.currencies SET decimal_places = 2 WHERE currency_code = 'BRL1';
UPDATE minicore.currencies SET decimal_places = 2 WHERE currency_code = 'BRLD';
UPDATE minicore.currencies SET decimal_places = 2 WHERE currency_code = 'BRLV';
UPDATE minicore.currencies SET decimal_places = 2 WHERE currency_code = 'BRLN';
UPDATE minicore.currencies SET decimal_places = 6 WHERE currency_code = 'USDC';
UPDATE minicore.currencies SET decimal_places = 6 WHERE currency_code = 'USDT';
UPDATE minicore.currencies SET decimal_places = 6 WHERE currency_code = 'EURC';
UPDATE minicore.currencies SET decimal_places = 8 WHERE currency_code = 'ETH';
UPDATE minicore.currencies SET decimal_places = 8 WHERE currency_code = 'POL';
UPDATE minicore.currencies SET decimal_places = 8 WHERE currency_code = 'SOL';

ALTER TABLE minicore.currencies ALTER COLUMN decimal_places SET NOT NULL

CREATE OR REPLACE FUNCTION minicore.fn_validate_transaction_amount_decimals()
RETURNS TRIGGER AS $$
DECLARE
    v_decimal_places SMALLINT;
BEGIN
    SELECT c.decimal_places
    INTO v_decimal_places
    FROM minicore.accounts a
    JOIN minicore.currencies c ON c.currency_code = a.currency_code
    WHERE a.account_id = NEW.account_id;

    IF NEW.amount != ROUND(NEW.amount, v_decimal_places) THEN
        RAISE EXCEPTION 'Amount % exceeds the maximum % decimal place(s) allowed for this account''s currency',
            NEW.amount, v_decimal_places;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql
